import{_ as r,a0 as a,w as s,s as d,ao as n,I as t,a1 as p,A as o,x as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"在大學培養學生們參與開源代碼開發的十四個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"在大學培養學生們參與開源代碼開發的十四個技巧 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在大學培養學生們參與開源代碼開發的十四個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在大學培養學生們參與開源代碼開發的十四個技巧 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20150921 14 tips for teaching open source development","title":"在大學培養學生們參與開源代碼開發的十四個技巧","tag":"201601","desc":""},"relativePath":"201601/20150921 14 tips for teaching open source development.md","filePath":"[post].md"}'),u={name:"201601/20150921 14 tips for teaching open source development.md"};function m(f,l,T,g,C,x){const e=a("Link");return s(),d("div",null,[l[22]||(l[22]=n('<h1 id="在大學培養學生們參與開源代碼開發的十四個技巧" tabindex="-1">在大學培養學生們參與開源代碼開發的十四個技巧 <a class="header-anchor" href="#在大學培養學生們參與開源代碼開發的十四個技巧" aria-label="Permalink to “在大學培養學生們參與開源代碼開發的十四個技巧”">​</a></h1><p><img src="https://opensource.com/sites/default/files/styles/image-full-size/public/images/education/EDU_TeachingOS.png" alt=""></p><p>學術界是培養和塑造未來的開源開發者的最佳平台。研究中發現，我們偶爾會開源自己編寫的軟件。這樣做有兩個理由，一是為了推廣自己編寫的工具的使用，二是為了瞭解人們使用這些工具時會遇到哪些問題。在這樣一個編寫研究軟件的背景下，我的任務就是為 Bradford 大學重新設計二年級的本科軟件工程課程。</p><p>這是一個挑戰，因為我所面對的 80 個學生是來自不同專業的，包括 IT、商務計算和軟件工程，這些學生將要在一起上課。最有難度的是，需要和這些編程經驗差距很大的學生一起編寫代碼。按照傳統，該課程允許學生選擇自己的小組，然後給他們佈置構建一個加油站資料庫系統的任務，最後提交報告作為評估的一部分。</p><p>而我決定重新設計課程，讓學生了解現實中的軟件團隊是如何協作的過程。根據學生的專業和編程技能，我將他們分為五、六個人一組。這是為了確保每個小組的整體水平相當，避免小組之間的不等。</p><h3 id="核心課程" tabindex="-1">核心課程 <a class="header-anchor" href="#核心課程" aria-label="Permalink to “核心課程”">​</a></h3><p>課程的形式改為講座和實踐課兩項結合在一起。然而實踐課作為指導過程，主要是老師監督各個小組的實踐進度以及他們如何處理客户和產品之間的關係。而傳統的教學方式由項目管理、軟件測試、工程需求分析以及類似主題的講座組成，再輔以實踐和導師會議。這些會議可以很好的考核學生的水平以及檢測出他們是否可以跟得上我們在講座部分中的軟件工程方法。本年的教學主題包括以下內容：</p><ul><li>工程需求分析</li><li>如何與客户及其他團隊成員互動</li><li>程序設計方法，如敏捷和極限編程方法</li><li>如何通過學習不同的軟件工程方法進行短期的水平提高</li><li>小組會議及文檔編寫</li><li>項目管理及項目進展圖表（甘特圖）</li><li>UML 圖表及系統描述</li><li>使用 Git 來進行代碼的版本控制</li><li>軟件測試及 BUG 跟蹤</li><li>使用開源庫</li><li>開源代碼許可及其選擇</li><li>軟件交付</li></ul><p>在這些講座之後，會有一些來自世界各地的嘉賓為我們説説他們在軟件交付過程中的經驗。我們也設法請來大學裏知識產權律師談關於軟件在英國的知識產權問題，以及如何處理軟件的知識產權問題。</p><h3 id="協作工具" tabindex="-1">協作工具 <a class="header-anchor" href="#協作工具" aria-label="Permalink to “協作工具”">​</a></h3><p>為了讓上述教學內容的順利進行，我們將會引入一些工具，並訓練學生在他們的項目中使用這些工具。如下：</p>',11)),t("ul",null,[l[5]||(l[5]=t("li",null,"Google Drive：團隊與導師之間進行共享的工具，暫時存儲用於描述項目的文檔和圖表、需求收集、會議紀要以及項目時間跟蹤等信息。採取這樣一個方式來監控並提供直接反饋到每個團隊，是非常有效的。",-1)),t("li",null,[p(e,{href:"https://basecamp.com/"},{default:o(()=>[...l[0]||(l[0]=[i("Basecamp",-1)])]),_:1}),l[1]||(l[1]=i("：同樣是用於分享文檔，在隨後的課程中，我們可能會考慮用它取代 Google Drive。",-1))]),t("li",null,[l[3]||(l[3]=i("BUG 報告工具，如 ",-1)),p(e,{href:"https://www.mantisbt.org/"},{default:o(()=>[...l[2]||(l[2]=[i("Mantis",-1)])]),_:1}),l[4]||(l[4]=i("：只能讓有限的用户免費提交 BUG。稍後我們提到的 Git 可以讓小組內的所有人員用做 BUG 提交。",-1))]),l[6]||(l[6]=t("li",null,"遠程視頻會議工具：在人員不在校內，甚至去了其他城市的情況下使用。學生們可以定期通過 Skype 來交流並記錄會議內容或則進行錄音作為今後其他用處。",-1)),l[7]||(l[7]=t("li",null,"同時，學生們的項目中還會用到大量的開源工具包。他們可以根據自己小組的項目需求來選擇自己使用的工具包和編程語言。唯一的條件是，這些項目必須開源，最後成果可以安裝到大學裏的實驗室，並且大多的研究人員都非常支持這個條件。",-1)),l[8]||(l[8]=t("li",null,"最後，所有團隊必須向客户交付他們的項目，包括完整的可以工作的軟件版本、文檔和他們自己選擇的開放源碼許可。大多數的團隊選擇了 GPLv3 許可證。",-1))]),l[23]||(l[23]=n('<h3 id="技巧和經驗教訓" tabindex="-1">技巧和經驗教訓 <a class="header-anchor" href="#技巧和經驗教訓" aria-label="Permalink to “技巧和經驗教訓”">​</a></h3><p>在最後，這一年過的很愉快，並且所有學生的項目都做的非常棒。這裏有一些我學到的經驗教訓，可能有助於提高明年的課程質量：</p><ol><li><p>提供各種各樣有趣的選擇項目給學生選擇。比如説，遊戲開發或者移動應用開發以及完成各種目標的項目等。建立普通的資料庫系統已經不能提起學生的興趣了，而參與到有趣的項目中去，學生本身就是自學者，同時可以幫助解決小組成員和小組之間的常見問題。再通過一個消息列表，學生們發表他們在測試中遇到的任何問題，以尋求其他人的幫助建議。然而，這種方法有一個缺點。外部考官建議我們使用統一種類型的項目和統一的編程語言以幫助縮小對學生的評估標準。</p></li><li><p>定期給學生在每一個階段的表現進行反饋。比方説，可以在和各個小組開指導會議的時候，或者每個階段進行反饋，以幫助他們在接下來的工作中自我改進。</p></li><li><p>學生更加願意與校外的客户一起協作。他們期待着與外部公司代表或校外人員協作，不過是為了獲得新體驗而已。與導師進行交流時，他們都能夠表現得很專業，這樣使得老師非常放心。</p></li><li><p>很多團隊版將開發單元測試的部分放到項目結束之後，從極限編程方法的角度來説，這是一個嚴重的禁忌。也許測試應包括在不同階段的評估中，來提醒他們需要並行開展軟件開發和單元測試。</p></li><li><p>在這個班的 80 個人裏邊，僅有 4 個女生，每個女生都分在不同的小組裏邊。我觀察到，男生們總是充分準備好來承擔起領隊角色，並將最有趣的代碼部分留給他們自己來編寫，女生則多大遵循安排或者是編寫文檔。出於某種原因，女生選擇不出頭，即使在女性輔導員鼓勵下，她們也不願編寫代碼。這仍然是一個需要解決的主要問題。</p></li><li><p>允許不同風格項目文檔，比方説，UML 圖表、狀態圖或其他形式的。讓學生學習這些並與其他課程融匯貫通來提高他們的學習經驗。</p></li><li><p>學生裏邊，有些是很好的開發人員，有些做商務計算的則沒有多少編程經驗。我們要鼓勵團隊共同努力，避免開發人員做得比那些只做會議記錄或文檔的其他成員更好的錯誤認知。我們常在輔導課程中鼓勵角色轉換，讓每個人都有機會學習如何編程。</p></li><li><p>小組與導師每週見面溝通是非常重要的，可以有效監督各個小組進展情況，還可以瞭解是誰做了大部分工作。通常，沒來參加會議的小組成員基本就是沒有參與到他們的團隊工作中去的，並且通過其他成員所提交的工作報告也可以確定哪些人不活躍。</p></li><li><p>我們鼓勵學生們把許可證附加到項目中去，使用外部庫以及和客户協作的時候要表明確切知識產權問題。 這樣可讓打破陳規，開拓思維，並瞭解真實的軟件交付問題。</p></li><li><p>給學生們自己選擇所用技術的空間。</p></li><li><p>助教是關鍵。同時管理 80 個學生顯然很有難度，特別是需要對他們進行評估的那幾周。明年我一定會找個助教來幫我一起管理各個小組。</p></li><li><p>實驗室的技術支持是非常重要的。大學裏的技術支持人員對於本課程是非常贊同的。他們正在考慮明年將虛擬機分配給每個團隊，這樣沒個團隊可以根據需要自行在虛擬機中安裝任何軟件。</p></li><li><p>團隊合作，相互幫助。大多數團隊自然而然的支持其他團隊成員，同時指導員在中間也幫助了不少。</p></li><li><p>來自其他同事的幫助會錦上添花。作為一名新的大學導師，我需要從經驗中學習，如果我想了解如何管理某些學生和團隊，或者對如何讓學生適應課程感到困惑時，我會通過多個方面來尋求建議。來自資深同事的支持對我來説是一種極大的鼓勵。</p></li></ol><p>最後，對於作為導師的我以及所有的學生來説，這都是個有趣的課程。在學習目標和傳統評分方案上還有有一些問題需解決，以減少教師的工作量。明年，我計劃會保留這種教學模式，並希望能夠提出更好的評分方案以及引入更多的軟件來幫助監督項目和控制代碼版本。</p><hr>',5)),t("p",null,[l[10]||(l[10]=i("via: ",-1)),p(e,{href:"http://opensource.com/education/15/9/teaching-open-source-development-undergraduates"},{default:o(()=>[...l[9]||(l[9]=[i("http://opensource.com/education/15/9/teaching-open-source-development-undergraduates",-1)])]),_:1})]),t("p",null,[l[14]||(l[14]=i("作者：",-1)),p(e,{href:"http://opensource.com/users/mariamkiran"},{default:o(()=>[...l[11]||(l[11]=[i("Mariam Kiran",-1)])]),_:1}),l[15]||(l[15]=i(" 譯者：",-1)),p(e,{href:"https://github.com/GHLandy"},{default:o(()=>[...l[12]||(l[12]=[i("GHLandy",-1)])]),_:1}),l[16]||(l[16]=i(" 校對：",-1)),p(e,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...l[13]||(l[13]=[i("Caroline",-1)])]),_:1})]),t("p",null,[l[19]||(l[19]=i("本文由 ",-1)),p(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...l[17]||(l[17]=[i("LCTT",-1)])]),_:1}),l[20]||(l[20]=i(" 原創編譯，",-1)),p(e,{href:"https://linux.cn/"},{default:o(()=>[...l[18]||(l[18]=[i("Linux中國",-1)])]),_:1}),l[21]||(l[21]=i(" 榮譽推出",-1))])])}const P=r(u,[["render",m]]);export{v as __pageData,P as default};
